package ru.main.explorer;
import android.app.*;import android.content.*;import android.net.Uri;import android.os.*;import java.io.*;import java.util.concurrent.atomic.*;

final class MapImport {
 interface InputFactory {InputStream open()throws Exception;}
 static void connect(MainActivity activity,Uri uri){ProgressDialog dialog=new ProgressDialog(activity);dialog.setMessage(Language.text(activity,R.string.connecting_local_map));dialog.setCancelable(false);dialog.show();new Thread(()->{boolean invalid=false;String error=null,description="";try(WorldMap candidate=WorldMap.open(activity,uri,null)){description=candidate.name+(candidate.vector?Language.text(activity,R.string.vector):Language.text(activity,R.string.raster))+Language.text(activity,R.string.zoom_levels)+candidate.minZoom+"–"+candidate.maxZoom;activity.getSharedPreferences("world-map",0).edit().putString("uri",uri.toString()).putLong("attached",System.currentTimeMillis()).commit();}catch(Exception failure){error=failure.getMessage();invalid=failure instanceof WorldMap.InvalidMap;}final boolean cannotCopy=invalid;final String message=error,info=description;activity.runOnUiThread(()->{if(activity.isFinishing()||activity.isDestroyed())return;dialog.dismiss();if(message==null){activity.mapConnected(info);}else if(cannotCopy)new AlertDialog.Builder(activity).setTitle(Language.text(activity,R.string.unsupported_map)).setMessage(message).setPositiveButton(Language.text(activity,R.string.close),null).show();else new AlertDialog.Builder(activity).setTitle(Language.text(activity,R.string.could_not_connect_directly)).setMessage(message+Language.text(activity,R.string.n_nchoose_mbtiles_from_your_local_downloads_folder_if_the_file_pr)).setPositiveButton(Language.text(activity,R.string.copy_2),(d,w)->copy(activity,()->activity.getContentResolver().openInputStream(uri))).setNegativeButton(Language.text(activity,R.string.close),null).show();});},"world-map-connect").start();}
 static void copy(MainActivity activity,InputFactory input){ProgressDialog dialog=new ProgressDialog(activity);dialog.setTitle(Language.text(activity,R.string.copying_map));dialog.setMessage(Language.text(activity,R.string.preparing));dialog.setCancelable(true);AtomicBoolean cancel=new AtomicBoolean();AtomicReference<InputStream> stream=new AtomicReference<>();dialog.setOnCancelListener(d->{cancel.set(true);InputStream in=stream.get();if(in!=null)new Thread(()->{try{in.close();}catch(IOException ignored){}},"map-import-cancel").start();});dialog.show();new Thread(()->{File temp=new File(activity.getFilesDir(),"world-import-"+java.util.UUID.randomUUID()+".part"),target=null;String error=null,description="";try{long last=0;try(InputStream in=input.open();FileOutputStream out=new FileOutputStream(temp)){if(in==null)throw new IOException(Language.text(activity,R.string.could_not_open_file));stream.set(in);byte[] buffer=new byte[262144];long bytes=0;int n;while((n=in.read(buffer))!=-1){if(cancel.get())throw new IOException(Language.text(activity,R.string.copy_cancelled));if(activity.getFilesDir().getUsableSpace()<n+32L*1024*1024)throw new IOException(Language.text(activity,R.string.not_enough_free_space_for_a_copy));out.write(buffer,0,n);bytes+=n;if(SystemClock.uptimeMillis()-last>400){last=SystemClock.uptimeMillis();String progress=String.format(Language.locale(activity),Language.text(activity,R.string.copied_gb),bytes/1e9);activity.runOnUiThread(()->{if(!activity.isDestroyed())dialog.setMessage(progress);});}}out.getFD().sync();}finally{stream.set(null);}if(cancel.get())throw new IOException(Language.text(activity,R.string.copy_cancelled));try(WorldMap candidate=WorldMap.open(activity,Uri.fromFile(temp),null)){description=candidate.name;}target=new File(activity.getFilesDir(),"world-"+System.currentTimeMillis()+".mbtiles");if(!temp.renameTo(target))throw new IOException(Language.text(activity,R.string.could_not_save_map));activity.getSharedPreferences("world-map",0).edit().putString("uri",Uri.fromFile(target).toString()).putLong("attached",System.currentTimeMillis()).commit();}catch(Exception failure){error=failure.getMessage();temp.delete();}final String message=error,info=description;activity.runOnUiThread(()->{if(activity.isFinishing()||activity.isDestroyed())return;dialog.dismiss();if(message==null)activity.mapConnected(info);else if(!cancel.get())new AlertDialog.Builder(activity).setTitle(Language.text(activity,R.string.map_not_connected)).setMessage(message).setPositiveButton(Language.text(activity,R.string.close),null).show();});},"world-map-copy").start();}
 static void catalog(MainActivity activity){new AlertDialog.Builder(activity).setTitle(Language.text(activity,R.string.detailed_world_map)).setMessage(Language.text(activity,R.string.vector_mbtiles_using_openmaptiles_or_protomaps_and_raster_mbtiles)).setPositiveButton(Language.text(activity,R.string.map_catalogue),(d,w)->activity.startActivity(new Intent(Intent.ACTION_VIEW,Uri.parse("https://quarrymapserver.org/downloads.html")))).setNeutralButton(Language.text(activity,R.string.connect_file),(d,w)->activity.chooseWorldMap()).setNegativeButton(Language.text(activity,R.string.close),null).show();}
}
